#!/bin/sh
# Prepare a fresh clone. Idempotent — safe to re-run at any time.
#
# Generated by development-guidelines/setup.swift, and tracked on purpose:
# the framework directory is gitignored, so it is not in a fresh clone and
# cannot be what you run first.

set -eu
cd "$(git rev-parse --show-toplevel)"

# .githooks/ is tracked; core.hooksPath is per-clone git config and cannot be
# committed. Git refuses to let a repository configure its own hook path, so
# this line is the one thing a clone genuinely cannot do for itself.
git config core.hooksPath .githooks
echo "✓ core.hooksPath = .githooks"

# What the hooks need in order to be worth having.
warnings=0

if ! command -v swift >/dev/null 2>&1; then
  echo "✗ swift is not on PATH — the hooks build before checking, so they will fail" >&2
  warnings=$((warnings + 1))
fi

if ! command -v quality-gate >/dev/null 2>&1; then
  echo "✗ quality-gate is not on PATH" >&2
  echo "  Where the hooks are a project's only automatic gate they refuse to run" >&2
  echo "  without it, rather than passing silently. Install it:" >&2
  echo "    git clone https://github.com/jpurnell/quality-gate-swift.git ~/.quality-gate-swift" >&2
  echo "    cd ~/.quality-gate-swift && ./scripts/install.sh" >&2
  warnings=$((warnings + 1))
fi

if [ "$warnings" -eq 0 ]; then
  echo "✓ swift and quality-gate found"
  echo ""
  echo "Ready. The hooks will run on your next commit."
else
  echo ""
  echo "Hooks are wired up, but $warnings prerequisite(s) are missing above."
fi

# An Xcode project also gets the gate inline in the issue navigator.
#
# The hooks block a bad commit; this puts the same findings where the code is being
# written, which is the difference between a rule and a habit. Both, not either: a build
# phase is advisory and lives in one project, while the hooks work for anyone, including
# people who never open Xcode.
#
# Not a SwiftPM build-tool plugin, because it cannot be one. Those run sandboxed with no
# network and restricted writes, and the gate runs `swift build`, `swift test` and reads an
# index store — and a plugin invoking a build from inside a build recurses.
proj=$(ls -d ./*.xcodeproj 2>/dev/null | head -1 || true)
if [ -n "${proj:-}" ]; then
  if ruby -e 'require "xcodeproj"' 2>/dev/null; then
    ruby - "$proj" <<'RUBY'
require 'xcodeproj'

MARKER = 'installed by scripts/bootstrap.sh'

# Advisory, deliberately. A phase that fails every build on a backlog that predates it is
# how a tool gets deleted rather than adopted; `quality-gate adopt` is the route to a clean
# gate on a codebase with history, and dropping the `|| true` is for after that.
#
# Three static checkers, never `--check all`: this runs on EVERY build, and `build`, `test`
# and `unreachable` would run a build inside the build.
script = <<~SH
  # Quality Gate (#{MARKER})
  if command -v quality-gate >/dev/null 2>&1; then
    quality-gate --format xcode --check safety --check concurrency --check fp-safety || true
  else
    echo "warning: quality-gate not installed — not checked"
  fi
SH

project = Xcodeproj::Project.open(ARGV[0])
changed = []
project.native_targets.reject(&:test_target_type?).each do |target|
  phase = target.shell_script_build_phases.find { |p| (p.shell_script || '').include?(MARKER) }
  phase ||= target.new_shell_script_build_phase('Quality Gate')
  phase.shell_script = script
  phase.shell_path = '/bin/sh'
  # "Based on dependency analysis" unchecked. With it checked and no declared outputs,
  # Xcode runs the phase once and then treats it as up to date forever — it looks
  # installed and silently stops running.
  phase.always_out_of_date = '1' if phase.respond_to?(:always_out_of_date=)
  changed << target.name
end
unless changed.empty?
  project.save
  puts "✓ Quality Gate build phase: #{changed.join(', ')}"
end
RUBY
  else
    echo "ℹ $proj found, but the xcodeproj gem is missing — no build phase installed."
    echo "  gem install xcodeproj, then re-run this script."
    echo "  Editing a .pbxproj any other way risks a malformed project file, which is worse"
    echo "  than not having the phase."
  fi
fi
